    /// <summary>
    /// Declines an invitation to an active group call via messageGroupCall. Can be called both by the sender and the receiver of the invitation
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> DeclineGroupCallInvitationAsync(long chatId = default, long messageId = default)
    {

           using var activity =  StartCallActivity("DeclineGroupCallInvitationAsync", typeof(DeclineGroupCallInvitation).FullName ?? "DeclineGroupCallInvitationAsync");

           try
           {
             return client.DeclineGroupCallInvitationAsync(chatId, messageId);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
